package main

import (
	"fmt"
	"sync"
)

// gen emits the given numbers on a channel and closes it.
func gen(nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out) // generator owns and closes its channel
		for _, n := range nums {
			out <- n
		}
	}()
	return out
}

// sq is one fan-out worker: it reads from in and writes squares to its own out.
func sq(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out) // each worker closes only its OWN output
		for n := range in {
			out <- n * n
		}
	}()
	return out
}

// merge fans in: it multiplexes multiple channels into one.
func merge(cs ...<-chan int) <-chan int {
	var wg sync.WaitGroup
	out := make(chan int)

	// One forwarder goroutine per input channel.
	output := func(c <-chan int) {
		defer wg.Done()
		for v := range c { // drain this input fully
			out <- v
		}
	}
	wg.Add(len(cs))
	for _, c := range cs {
		go output(c)
	}

	// Close out exactly once, after ALL forwarders finish.
	go func() {
		wg.Wait()
		close(out)
	}()
	return out
}

func main() {
	in := gen(2, 3, 4, 5, 6)

	// Fan-out: start 3 workers all reading from the same input channel.
	c1 := sq(in)
	c2 := sq(in)
	c3 := sq(in)

	// Fan-in: merge their outputs and sum them.
	sum := 0
	for v := range merge(c1, c2, c3) {
		sum += v
	}
	// 4 + 9 + 16 + 25 + 36 = 90 (arrival order varies, sum is deterministic).
	fmt.Println("sum of squares:", sum)
}

package main

import (
	"context"
	"fmt"
	"sync"
)

func gen(ctx context.Context, nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for _, n := range nums {
			select {
			case out <- n:
			case <-ctx.Done():
				return // stop producing if cancelled
			}
		}
	}()
	return out
}

func sq(ctx context.Context, in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			select {
			case out <- n * n:
			case <-ctx.Done():
				return // don't block forever if downstream stopped
			}
		}
	}()
	return out
}

func merge(ctx context.Context, cs ...<-chan int) <-chan int {
	var wg sync.WaitGroup
	out := make(chan int)
	output := func(c <-chan int) {
		defer wg.Done()
		for v := range c {
			select {
			case out <- v:
			case <-ctx.Done():
				return
			}
		}
	}
	wg.Add(len(cs))
	for _, c := range cs {
		go output(c)
	}
	go func() { wg.Wait(); close(out) }()
	return out
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel() // ensures all stages can unwind even on early return

	in := gen(ctx, 1, 2, 3, 4, 5, 6, 7, 8)
	c1, c2 := sq(ctx, in), sq(ctx, in) // fan-out width 2

	// Consume only the first 3 results, then cancel: no goroutine leaks.
	out := merge(ctx, c1, c2)
	got := 0
	for v := range out {
		fmt.Println("result:", v)
		got++
		if got == 3 {
			cancel() // tell every stage to stop
			break
		}
	}
	// Drain remaining values so forwarders that already started a send can finish
	// and exit; out will be closed once wg.Wait completes.
	for range out {
	}
	fmt.Println("done, consumed:", got)
}
